 req:=gen_random_uuid();r:=public.claim_email_token_refresh(p,c,version,identity,req,true);
 perform pg_temp.check(r->>'state'='claimed','email verified renewal claim');
 tokens:=jsonb_build_object('accessToken','new-access','refreshToken','new-refresh','expiresAt',now()+interval '1 hour');
 r:=public.finish_email_token_refresh(p,c,req,'success',tokens);
 perform pg_temp.check(r->>'state'='saved' and r->>'permissionState'='confirmed','email omitted renewal scope inherits verified grant');
 perform pg_temp.check((select provider_metadata->>'scopeEvidence'='refresh_inherited' and provider_metadata->>'preserve'='yes' from public.email_configurations where id=c),'email inheritance provenance preserved without clobbering provider metadata');
 select credential_version into version from public.email_configurations where id=c;
 req:=gen_random_uuid();perform public.claim_email_token_refresh(p,c,version,identity,req,true);
 tokens:=tokens||'{"scope":"User.Read","refreshToken":"narrowed-rotation"}';
 r:=public.finish_email_token_refresh(p,c,req,'success',tokens);
 perform pg_temp.check(r->>'state'='permissions_incomplete' and not r ? 'accessToken','email narrower refreshed grant returns no usable credential');
 perform pg_temp.check((select refresh_token='narrowed-rotation' and token_status='permissions_incomplete' and scopes=array['User.Read'] and credential_version=version+1 from public.email_configurations where id=c),'email rotation and permission hold saved atomically');
 perform pg_temp.check((select refresh_status='permissions_incomplete' and completed_version=version+1 from public.email_token_refreshes where request_id=req),'email renewal ledger reflects hold');
 perform pg_temp.check(public.finish_email_token_refresh(p,c,req,'success',tokens)=r,'email lost hold response replays exact saved outcome');
 r:=public.claim_email_token_refresh(p,c,version,identity,gen_random_uuid(),false);
 perform pg_temp.check(r->>'state'='permissions_incomplete' and not r ? 'accessToken','email stale config cannot bypass reduced permissions');
 update public.email_configurations set scopes=array['User.Read','Calendars.ReadWrite','Mail.Read','Mail.Send'],provider_metadata='{"scopeEvidence":"provider_response"}',token_status='healthy' where id=c returning credential_version into version;
 req:=gen_random_uuid();perform public.claim_email_token_refresh(p,c,version,identity,req,true);
 r:=public.finish_email_token_refresh(p,c,req,'success',tokens||'{"scope":null}');
 perform pg_temp.check(r->>'state'='permissions_unconfirmed','email explicit null scope cannot inherit earlier grant');
 update public.email_configurations set scopes=array['User.Read','Calendars.ReadWrite','Mail.Read','Mail.Send'],provider_metadata='{"scopeEvidence":"provider_response"}',token_status='healthy' where id=c returning credential_version into version;
 req:=gen_random_uuid();perform public.claim_email_token_refresh(p,c,version,identity,req,true);
 update public.email_configurations set scopes=array['User.Read'] where id=c;
 r:=public.finish_email_token_refresh(p,c,req,'success',tokens);
 perform pg_temp.check(r->>'state'='connection_changed','email permission edits fence in-flight renewal');
 perform pg_temp.check((select scopes=array['User.Read'] from public.email_configurations where id=c),'email stale completion cannot restore removed permissions');
end$$;
select count(*) as passed from checks; ROLLBACK;
